using System.Windows;using System.Windows.Controls;using MizanDesktop.Services;
namespace MizanDesktop.Views; public partial class InventoryView:UserControl{readonly AppRepository _repo;public InventoryView(AppRepository repo){InitializeComponent();_repo=repo;Refresh();}void Refresh(){var rows=_repo.InventoryReport();Grid.ItemsSource=rows.Select(x=>new{Product=x.Product,Quantity=x.Quantity,Cost=x.Cost,Value=x.Value}).ToList();Summary.Text=$"عدد الأصناف: {rows.Count}    |    قيمة المخزون: {rows.Sum(x=>x.Value):N2}";}void Count_Click(object s,RoutedEventArgs e){var low=_repo.Products.Where(p=>p.Quantity<=p.MinQuantity).ToList();MessageBox.Show(low.Count==0?"لا توجد أصناف تحت حد التنبيه.":"أصناف تحتاج جرد/تزويد:\n"+string.Join("\n",low.Select(p=>$"{p.Name}: {p.Quantity:N2}")),"الجرد السريع");}void Refresh_Click(object s,RoutedEventArgs e)=>Refresh();}
